"""Own complete source-header qualification and typed historical boundaries."""
import hashlib
import json
from pathlib import Path

BASE=Path('docs/audits/observer-source-headers-20261011')
VALUES=Path('docs/audits/observer-source-value-acceptance-20261011')
PUBLICATION=Path('docs/audits/observer-source-value-publication-repair-20261011')
CENSUS=Path('docs/audits/observer-header-source-census-20261010')
DISPLAY=Path('docs/audits/observer-display-contract-20261010')
PREDICATE=Path('docs/audits/observer-predicate-values-20261010')
SCALAR=Path('docs/audits/observer-scalar-values-20261010')
REGEX=Path('docs/audits/observer-regex-values-20261010')
REVISION='eec7e0a8e43df9aaff82176eb05e73d862518426'
SCOPE=('Complete source-selected original own argument-header hypotheses and unchanged source-header parent acceptance only. '
       'Every full known value, source member/order/role and inherited evidence role retains. '
       'Current public displays are explicitly conditional qualified constructions; original settings/formatter/flags/encoding, '
       'reference/referent/receiver identity and private framework/eval meanings remain typed unmeasured boundaries. '
       'No scalar/prefix/wildcard substitutes for an unknown. Source do differs from diagnostic require. '
       'Original raw-header comparison, observer/raw/native/private and visual acceptance remain separately owned.')


def need(condition,cause):
    if not condition:
        raise ValueError(cause)


def canonical(value):
    return (json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True,allow_nan=False)+'\n').encode()


def pin(raw):
    return dict(bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest())


def read(path):
    return json.loads(path.read_bytes())


def load(name):
    return read(BASE/name)


def same(left,right):
    return canonical(left)==canonical(right)


def save(name,value):
    path=BASE/name
    need(not path.exists(),'retain complete first source-header evidence: '+name)
    path.write_bytes(canonical(value))


def inputs():
    return [CENSUS/n for n in ('source-models.json','census.json','obligation-plan.json')] + [
        VALUES/n for n in ('product-qualified.json','contracts.json','proof.json','manifest.json')] + [
        PUBLICATION/n for n in ('proof.json','manifest.json')] + [
        DISPLAY/n for n in ('repaired-catalogue.json','repaired-hypotheses.json','repaired-native.json',
                           'repaired-joined.json','oracle_repaired.py','model_repaired.py','qualified-proof.json')] + [
        PREDICATE/n for n in ('predicate-values-qualified.json','fixture-plan-qualified.json','native-qualified.json')] + [
        SCALAR/n for n in ('scalars.json','plan.json','native.json')] + [
        REGEX/n for n in ('regexes.json','plan.json','native.json')]

"""Whole original source-header parent, completed children and raw-join successor."""
import re
import subprocess
from pathlib import Path
from common import BASE, REVISION, SCOPE, need

TASK=Path('docs/tasks/SEMANTIC-INTROSPECTION-MCP-FRONTIER.md')


def block(text,identifier):
    marker='- ID: `'+identifier+'`\n'
    need(text.count(marker)==1,'unique complete original source-header task')
    start=text.index(marker);end=text.find('\n- ID:',start+1)
    return text[start:end if end>=0 else len(text)]


def contract(text):
    return {field:re.search(r'^  '+field+r': `(.*)`$',text,re.M).group(1)
            for field in ('Goal','Acceptance','Children') if re.search(r'^  '+field+':',text,re.M)}


def derive(current=None):
    owner=(BASE/'scope.txt').read_text().splitlines()[0];parent=owner.rsplit('.',1)[0];outer=parent.rsplit('.',1)[0]
    values=parent+'.2'
    identifiers=[owner,parent,parent+'.1',values,values+'.1',values+'.2',values+'.3',outer,outer+'.1',outer+'.3']
    command=['git','--no-replace-objects','show',REVISION+':'+str(TASK)]
    actual=subprocess.run(command,capture_output=True,text=True)
    need(actual.returncode==0 and actual.stderr=='','whole fixed original source-header parent acceptance')
    originals={identifier:block(actual.stdout,identifier) for identifier in identifiers}
    text=TASK.read_text() if current is None else current
    for identifier,original in originals.items():
        need(contract(block(text,identifier))==contract(original),'complete unchanged source-header/child/raw-join acceptance and topology')
    for identifier in (parent+'.1',values,values+'.1',values+'.2',values+'.3',outer+'.1'):
        need('\n  Status: `done`\n' in originals[identifier] and '\n  Status: `done`\n' in block(text,identifier),
             'committed and current completed source-header prerequisite child')
    need('\n  Status: `pending`\n' in originals[outer+'.3'],'original raw-join successor was separately pending at the selected epoch')
    return dict(revision=REVISION,command=command,original_bodies=originals,scope=SCOPE)

"""Evaluate only fully known conditional headers; preserve every unresolved source slot."""
from common import BASE, SCOPE, load, need, save


def evaluate(product):
    result=[]
    table=product['current_construction_cases']
    for header in product['headers']:
        form=header['current_conditional_form'];tokens=[];unresolved=[]
        for slot in form['slots']:
            spellings=[]
            for identifier in slot['cases']:
                evidence=table[identifier]
                token=(evidence['case']['display_token'] if evidence['kind']=='predicate'
                       else evidence['case']['display']['token'])
                if token not in spellings:
                    spellings.append(token)
            if slot['unresolved_reference_token'] or len(spellings)!=1:
                unresolved.append(dict(argument_id=slot['argument_id'],qualified_current_alternatives=spellings,
                    reference_token_unmeasured=slot['unresolved_reference_token']))
            else:
                tokens.append(spellings[0])
        marker=header['expression']['kind']=='block_eval_source_marker'
        known=None
        if not unresolved and not marker:
            if form['remaining_arguments']:
                tokens.append('...')
            known=header['expression']['function']+'('+', '.join(tokens)+')'
        result.append(dict(header_id=header['id'],path=header['path'],profile=form['profile'],
            known_conditional_header=known,unresolved_slots=unresolved,source_eval_marker=marker,
            complete_source_argument_ids=header['source_argument_ids'],hidden_argument_ids=form['hidden_argument_ids'],
            meaning='Source-selected conditional public-grammar hypothesis only; unresolved slots are typed evidence boundaries and supply no encoded token or wildcard matcher.'))
    return dict(scope=SCOPE,headers=result,
        role='Generated known conditional header text and complete unresolved slot allocation only; no original or new native-header capture/comparison.')


if __name__=='__main__':
    need(not (BASE/'original-raw-intake.json').exists(),'known conditional headers before own original raw intake')
    save('current-headers.json',evaluate(load('headers.json')))
    print('PASS every fully known conditional header and complete unresolved/hidden argument allocation; original profile/native/private boundaries remain unmeasured.')

"""Select complete source header expressions before any own original raw intake."""
from common import BASE, CENSUS, VALUES, DISPLAY, PREDICATE, SCALAR, REGEX, SCOPE, canonical, inputs, load, need, pin, read, same, save

PROFILE={'MaxArgLen':64,'MaxArgNums':8,'MaxEvalLen':0,'RefArgFormatter':None}
ORIGINAL={
    'settings_formatter':'unmeasured',
    'scalar_flags_encoding':'unmeasured',
    'regexp_flags_encoding_provider_identity':'unmeasured',
    'reference_referent_receiver_identity':'unmeasured',
    'private_framework_eval_meanings':'unmeasured',
    'encoded_original_header_equality':'not compared in this source-selected slice',
}


def cases():
    result={}
    for kind,directory in [('scalar',SCALAR),('regex',REGEX)]:
        for row in read(directory/'plan.json')['cases']:
            identifier=kind+':'+row['id']
            need(identifier not in result,'unique complete current constructor case')
            result[identifier]=dict(kind=kind,case=row,
                meaning='Dated qualified source-neutral current construction only; no original flags/settings/identity attribution.')
    for fixture in read(PREDICATE/'fixture-plan-qualified.json')['fixtures']:
        identifier='predicate:'+fixture['name']
        need(identifier not in result,'unique whole predicate fixture')
        result[identifier]=dict(kind='predicate',case=fixture,
            meaning='Dated qualified source guard construction only; a logical-zero source field is not an encoded-token oracle.')
    return result


def bindings(qualified,case_table):
    predicate={tuple(r['path']):r for r in read(PREDICATE/'predicate-values-qualified.json')['rows']}
    result={}
    for row in qualified['operands']:
        path=row['path'];value=row['qualification'];kind=value['kind'];key=pin(canonical(path))['sha256']
        selected=[]
        if kind=='qualified whole guard construction':
            source=predicate[tuple(path)]
            selected=[identifier for identifier,item in case_table.items() if item['kind']=='predicate'
                      and item['case']['value_class']==source['value_class']]
        elif kind=='qualified complete scalar value':
            selected=[identifier for identifier,item in case_table.items() if item['kind']=='scalar'
                      and item['case']['value_id']==value['value_id']]
        elif kind=='qualified whole authored regex':
            selected=[identifier for identifier,item in case_table.items() if item['kind']=='regex'
                      and item['case']['body']==value['authored']['body']]
        else:
            need(kind=='source reference role and kind only','closed complete source-header operand qualification')
        need(bool(selected) or kind=='source reference role and kind only','every known complete value has qualified construction evidence')
        need(key not in result,'unique whole source operand path')
        result[key]=dict(source=row,current_construction_cases=selected,
            original_token=dict(state='unmeasured original token',qualification='complete known source value/role retained; original settings/flags/identity are not selected',
                substitute_scalar_prefix_wildcard=False))
    return result


def walk(node,path):
    if isinstance(node,dict):
        yield path,node
        for field in sorted(node):
            yield from walk(node[field],path+[field])
    elif isinstance(node,list):
        for index,member in enumerate(node):
            yield from walk(member,path+[index])


def active_cases(binding,case_table):
    return [identifier for identifier in binding['current_construction_cases']
            if case_table[identifier]['kind']=='predicate' or case_table[identifier]['case']['limit']==64]


def product():
    source=read(CENSUS/'source-models.json')
    qualified=read(VALUES/'product-qualified.json')['source_values']
    table=cases();operands=bindings(qualified,table)
    by_path={tuple(v['source']['path']):identifier for identifier,v in operands.items()}
    headers=[];header_paths={};used=set()
    for path,node in walk(source['modes'],['modes']):
        if 'function' not in node or 'arguments' not in node:
            continue
        need(type(node['function']) is str and type(node['arguments']) is list,'closed source call/header schema')
        argument_ids=[]
        for index,argument in enumerate(node['arguments']):
            arg_path=tuple(path+['arguments',index])
            identifier=by_path[arg_path]
            need(same(operands[identifier]['source']['input'],argument),'whole source/header operand association')
            argument_ids.append(identifier);used.add(identifier)
        visible=argument_ids[:8]
        header_id=pin(canonical(path))['sha256'];header_paths[tuple(path)]=header_id
        kind='block_eval_source_marker' if node['function']=='eval {...}' else 'source_call_header_expression'
        headers.append(dict(id=header_id,path=path,source_metadata={k:v for k,v in node.items() if k!='arguments'},
            source_argument_ids=argument_ids,
            expression=dict(kind=kind,function=node['function'],opening='' if kind=='block_eval_source_marker' else '(',
                argument_ids=argument_ids,separator=', ',closing='' if kind=='block_eval_source_marker' else ')',
                original_profile_parameter=ORIGINAL),
            current_conditional_form=dict(profile=PROFILE,visible_argument_ids=visible,hidden_argument_ids=argument_ids[8:],
                remaining_arguments=len(argument_ids)>8,
                slots=[dict(argument_id=identifier,cases=active_cases(operands[identifier],table),
                    unresolved_reference_token=operands[identifier]['source']['qualification']['kind']=='source reference role and kind only')
                    for identifier in visible],
                qualification='Complete source-selected expression under the dated public grammar; no original encoded-header equality or reference token is asserted.')))
    def skeleton(node,path):
        if tuple(path) in header_paths:
            return dict(source_header=header_paths[tuple(path)])
        if isinstance(node,dict):
            return {key:skeleton(value,path+[key]) for key,value in node.items()}
        if isinstance(node,list):
            return [skeleton(value,path+[index]) for index,value in enumerate(node)]
        return node
    allocation=skeleton(source['modes'],['modes'])
    loads=[dict(path=path+['load'],source_operator='do',diagnostic_marker=node['load'],
                diagnostic_marker_is_source_operator=False,
                qualification='Whole inherited source/public diagnostic boundary; source do is not rewritten to require.')
           for path,node in walk(source['modes'],['modes']) if 'load' in node]
    return dict(scope=SCOPE,original_unmeasured=ORIGINAL,current_profile=PROFILE,
        operands=operands,current_construction_cases=table,headers=headers,source_allocation=allocation,loads=loads,
        unframed_operand_ids=[identifier for identifier in operands if identifier not in used],
        source_frame_contracts=pin(canonical(source['frame_model'])),
        source_scope=source['scope'],source_value_scope=qualified['scope'],
        display_contract_scope=read(DISPLAY/'repaired-catalogue.json')['role'],
        inputs={str(path):pin(path.read_bytes()) for path in inputs()},
        raw_comparison='not performed; every whole hypothesis is selected before own original raw-header comparison')


if __name__=='__main__':
    need(not (BASE/'original-raw-intake.json').exists(),'complete source hypotheses before own original raw intake')
    selected=product()
    save('headers.json',selected)
    save('selection.json',dict(scope=SCOPE,product=pin(canonical(selected)),original_raw_intake_present=False,
        programmes={str(p):pin(p.read_bytes()) for p in sorted(BASE.glob('*.py'))}))
    print('PASS complete source-selected header expressions, full argument/value/order/role and conditional public grammar, typed original uncertainties and do/diagnostic roles before raw comparison.')

"""Independent direct-source frame/operand traversal and full expression reconstruction."""
import json
from common import CENSUS, VALUES, DISPLAY, PREDICATE, SCALAR, REGEX, SCOPE, canonical, inputs, need, pin, read, same


def nodes(source):
    pending=[(['modes'],source['modes'])];result=[]
    while pending:
        path,node=pending.pop()
        if isinstance(node,dict):
            result.append((path,node))
            pending.extend((path+[key],node[key]) for key in sorted(node,reverse=True))
        elif isinstance(node,list):
            pending.extend((path+[index],node[index]) for index in reversed(range(len(node))))
    return result


def expected():
    source=read(CENSUS/'source-models.json');parent=read(VALUES/'product-qualified.json')
    original=parent['source_values'];visited=nodes(source)
    direct=[]
    for path,node in visited:
        if 'role' in node and ('kind' in node or 'expression' in node):
            schema=node.get('kind', 'context_scalar' if 'source_value' in node else 'context_reference')
            direct.append(dict(path=path,input=node,schema=schema))
    need(same(direct,[{k:row[k] for k in ('path','input','schema')} for row in original['operands']]),
         'independent complete direct-source operand/schema/order allocation')
    table={};ordered=[]
    for kind,directory in [('scalar',SCALAR),('regex',REGEX)]:
        for row in read(directory/'plan.json')['cases']:
            identifier=kind+':'+row['id'];ordered.append(identifier)
            table[identifier]=dict(kind=kind,case=row,
                meaning='Dated qualified source-neutral current construction only; no original flags/settings/identity attribution.')
    for row in read(PREDICATE/'fixture-plan-qualified.json')['fixtures']:
        identifier='predicate:'+row['name'];ordered.append(identifier)
        table[identifier]=dict(kind='predicate',case=row,
            meaning='Dated qualified source guard construction only; a logical-zero source field is not an encoded-token oracle.')
    need(len(table)==len(ordered),'whole unique ordered current construction population')
    guards={tuple(r['path']):r for r in read(PREDICATE/'predicate-values-qualified.json')['rows']}
    scalars={tuple(r['path']):r for r in read(SCALAR/'scalars.json')['members']}
    regexes={tuple(r['path']):r for r in read(REGEX/'regexes.json')['members']}
    authored={r['helper']:r for r in read(REGEX/'regexes.json')['authored']}
    bindings={};paths={}
    for row in original['operands']:
        path=tuple(row['path']);schema=row['schema'];selected=[]
        if path in guards:
            selected=[identifier for identifier in ordered if table[identifier]['kind']=='predicate'
                      and table[identifier]['case']['value_class']==guards[path]['value_class']]
        elif schema in ('scalar','context_scalar'):
            value_id=scalars[path]['value']
            selected=[identifier for identifier in ordered if table[identifier]['kind']=='scalar'
                      and table[identifier]['case']['value_id']==value_id]
        elif schema=='regex_source':
            body=authored[regexes[path]['helper']]['body']
            selected=[identifier for identifier in ordered if table[identifier]['kind']=='regex'
                      and table[identifier]['case']['body']==body]
        else:
            need(schema in ('reference','context_reference'),'independent closed original reference schema')
        identifier=pin(canonical(list(path)))['sha256'];paths[path]=identifier
        bindings[identifier]=dict(source=row,current_construction_cases=selected,
            original_token=dict(state='unmeasured original token',
                qualification='complete known source value/role retained; original settings/flags/identity are not selected',
                substitute_scalar_prefix_wildcard=False))
    profile=dict(MaxArgLen=64,MaxArgNums=8,MaxEvalLen=0,RefArgFormatter=None)
    unknown=dict(settings_formatter='unmeasured',scalar_flags_encoding='unmeasured',
        regexp_flags_encoding_provider_identity='unmeasured',reference_referent_receiver_identity='unmeasured',
        private_framework_eval_meanings='unmeasured',encoded_original_header_equality='not compared in this source-selected slice')
    headers=[];lookup={};used=set()
    for path,node in visited:
        if not {'function','arguments'}<=set(node):
            continue
        need(type(node['function']) is str and type(node['arguments']) is list,'independent closed source frame/argument schema')
        identifiers=[]
        for index,argument in enumerate(node['arguments']):
            identifier=paths[tuple(path+['arguments',index])]
            need(same(bindings[identifier]['source']['input'],argument),'independent whole source argument/header association')
            identifiers.append(identifier);used.add(identifier)
        kind='block_eval_source_marker' if node['function']=='eval {...}' else 'source_call_header_expression'
        identifier=pin(canonical(path))['sha256'];lookup[tuple(path)]=identifier
        slots=[]
        for binding in identifiers[:profile['MaxArgNums']]:
            active=[case for case in bindings[binding]['current_construction_cases']
                    if table[case]['kind']=='predicate' or table[case]['case']['limit']==profile['MaxArgLen']]
            slots.append(dict(argument_id=binding,cases=active,
                unresolved_reference_token=bindings[binding]['source']['qualification']['kind']=='source reference role and kind only'))
        headers.append(dict(id=identifier,path=path,source_metadata={key:node[key] for key in node if key!='arguments'},
            source_argument_ids=identifiers,
            expression=dict(kind=kind,function=node['function'],opening='(' if kind=='source_call_header_expression' else '',
                argument_ids=identifiers,separator=', ',closing=')' if kind=='source_call_header_expression' else '',
                original_profile_parameter=unknown),
            current_conditional_form=dict(profile=profile,visible_argument_ids=identifiers[:8],hidden_argument_ids=identifiers[8:],
                remaining_arguments=len(identifiers)>8,slots=slots,
                qualification='Complete source-selected expression under the dated public grammar; no original encoded-header equality or reference token is asserted.')))
    # Restore each frame from its exact source metadata and complete argument
    # bindings. This preserves every non-frame phase/group/evidence field too.
    def allocate(node,path):
        if tuple(path) in lookup:
            return {'source_header':lookup[tuple(path)]}
        if isinstance(node,list):
            return [allocate(value,path+[index]) for index,value in enumerate(node)]
        if isinstance(node,dict):
            return {key:allocate(node[key],path+[key]) for key in node}
        return node
    loads=[]
    for path,node in visited:
        if 'load' in node:
            loads.append(dict(path=path+['load'],source_operator='do',diagnostic_marker=node['load'],
                diagnostic_marker_is_source_operator=False,
                qualification='Whole inherited source/public diagnostic boundary; source do is not rewritten to require.'))
    return dict(scope=SCOPE,original_unmeasured=unknown,current_profile=profile,operands=bindings,
        current_construction_cases=table,headers=headers,source_allocation=allocate(source['modes'],['modes']),loads=loads,
        unframed_operand_ids=[identifier for identifier in bindings if identifier not in used],
        source_frame_contracts=pin(canonical(source['frame_model'])),source_scope=source['scope'],source_value_scope=original['scope'],
        display_contract_scope=read(DISPLAY/'repaired-catalogue.json')['role'],inputs={str(p):pin(p.read_bytes()) for p in inputs()},
        raw_comparison='not performed; every whole hypothesis is selected before own original raw-header comparison')


def conditional(expected):
    rows=[];table=expected['current_construction_cases']
    for header in expected['headers']:
        form=header['current_conditional_form'];unresolved=[];tokens=[]
        for slot in form['slots']:
            alternatives=[]
            for identifier in slot['cases']:
                item=table[identifier]
                spelling=item['case']['display_token'] if item['kind']=='predicate' else item['case']['display']['token']
                if spelling not in alternatives:
                    alternatives.append(spelling)
            if not slot['unresolved_reference_token'] and len(alternatives)==1:
                tokens+=alternatives
            else:
                unresolved.append(dict(argument_id=slot['argument_id'],qualified_current_alternatives=alternatives,
                    reference_token_unmeasured=slot['unresolved_reference_token']))
        marker=header['expression']['kind']=='block_eval_source_marker'
        if not unresolved and not marker:
            all_tokens=tokens+(['...'] if form['remaining_arguments'] else [])
            text=header['source_metadata']['function']+'('+', '.join(all_tokens)+')'
        else:
            text=None
        rows.append(dict(header_id=header['id'],path=header['path'],profile=form['profile'],known_conditional_header=text,
            unresolved_slots=unresolved,source_eval_marker=marker,complete_source_argument_ids=header['source_argument_ids'],
            hidden_argument_ids=form['hidden_argument_ids'],
            meaning='Source-selected conditional public-grammar hypothesis only; unresolved slots are typed evidence boundaries and supply no encoded token or wildcard matcher.'))
    return dict(scope=SCOPE,headers=rows,
        role='Generated known conditional header text and complete unresolved slot allocation only; no original or new native-header capture/comparison.')


def validate(product,current):
    need(product['scope']==SCOPE,'unchanged complete source-header qualification scope')
    wanted=expected()
    need(set(product)==set(wanted),'closed complete source-header product schema')
    for field,value in wanted.items():
        need(same(product[field],value),'entire independent source-header field: '+field)
    headers={row['id']:row for row in product['headers']}
    def restore(node):
        if isinstance(node,dict) and set(node)=={'source_header'}:
            header=headers[node['source_header']]
            return dict(header['source_metadata'],arguments=[product['operands'][identifier]['source']['input']
                for identifier in header['source_argument_ids']])
        if isinstance(node,dict):
            return {key:restore(value) for key,value in node.items()}
        if isinstance(node,list):
            return [restore(value) for value in node]
        return node
    need(same(restore(product['source_allocation']),read(CENSUS/'source-models.json')['modes']),
         'whole original source modes reconstruct from complete header expressions and unframed evidence')
    wanted_current=conditional(wanted)
    need(same(current,wanted_current),'entire independent known conditional header/unresolved/hidden allocation')
    return dict(source_headers=pin(canonical(wanted)),conditional_headers=pin(canonical(wanted_current)),
        restored_modes=pin(canonical(restore(product['source_allocation']))),scope=SCOPE)


def public_contract():
    namespace={'__name__':'header_qualified_public_oracle'}
    programme=DISPLAY/'oracle_repaired.py'
    exec(compile(programme.read_bytes(),str(programme),'exec'),namespace)
    result=namespace['validate'](catalogue=read(DISPLAY/'repaired-catalogue.json'),
        hypotheses=read(DISPLAY/'repaired-hypotheses.json'),wire=json.loads(read(DISPLAY/'repaired-native.json')['stdout']),
        products=read(DISPLAY/'repaired-joined.json')['products'])
    parent=read(VALUES/'product-qualified.json')['public_constructions']
    for kind,directory in [('predicate',PREDICATE),('scalar',SCALAR),('regex',REGEX)]:
        fixture=parent[kind];native=fixture['native'];plan=pin(canonical(fixture['plan']));driver=pin(fixture['driver'].encode())
        need(type(native['status']) is int and native['status']==0 and native['stderr']=='','actual typed full inherited public construction success')
        if kind=='predicate':
            need(native['plan']==plan and native['driver']==driver,'whole inherited actual predicate plan/driver binding')
        else:
            need(native['inputs'][str(directory/'plan.json')]==plan
                 and native['inputs'][str(directory/'native.pl')]==driver,'whole inherited actual scalar/regex plan/driver binding')
    return dict(programme=pin(programme.read_bytes()),whole_public_products=pin(canonical(result)),
        meaning='Complete dated public grammar and whole constructor receipt binding only; original formatter/settings/native identities remain unmeasured.')
